// THE NON-EDITOR CLAIM. A field answers a focus request by OPENING, which is
// right after a + and wrong after a pick: the value is already there. A row
// answers the same deferred request by taking the caret and nothing else.
import { createEffect, on } from 'solid-js';
import { clearFocusFor, editFocus, editFocusMode } from '../shared/edit-hook.jsx';
import { focusWithoutJump } from './field.jsx';

// A row address names the PLACE, not the node: the same party stands on more
// than one card, so the holder and the predicate say which row was written.
export function rowAddress(holder: string, part: string, card?: string | null): string {
  if (!holder || !part) return '';
  return card ? `${holder}|${part}|${card}` : `${holder}|${part}`;
}

export function claimRowFocus(address: () => string, el: () => HTMLElement | undefined): void {
  createEffect(on(editFocus, (wanted) => {
    const mine = address();
    if (!wanted || !mine || wanted !== mine || editFocusMode() !== 'row') return;
    // The rerender builds the row before it inserts it, and focus on a node
    // that hangs outside the document is a no-op — so the claim waits for the
    // insertion. A row that never lands leaves the request standing; only a
    // row answers it, so no field opens on it.
    queueMicrotask(() => {
      const node = el();
      if (!node || !node.isConnected) return;
      focusWithoutJump(node);
      clearFocusFor(mine);
    });
  }));
}
