import { Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { onCleanup, onMount } from 'solid-js';
import { DragGhost } from '../drag.jsx';
import { attachDragLayers, dragItem, dragPosition } from './drag-gesture.js';

export function DragLayer(): JSX.Element {
  onMount(() => {
    const off = attachDragLayers();
    onCleanup(off);
  });
  return (
    <Show when={dragItem()}>{(item) => (
      <DragGhost
        name={item().label}
        x={dragPosition().x}
        y={dragPosition().y}
      />
    )}</Show>
  );
}
